Separar o Navigator em dois grupos (AuthStack/AppStack) condicionados a um estado de autenticação reativo (Context/Zustand), e usar um hook de guarda que redireciona automaticamente.

```tsx
function RootNavigator() {
  const { isAuthenticated } = useAuthState(); // reativo, atualizado por login/logout/expiração
  return (
    <Stack.Navigator>
      {isAuthenticated ? (
        <Stack.Group>{/* Home, Financeiro, ... */}</Stack.Group>
      ) : (
        <Stack.Group>{/* Login, Register */}</Stack.Group>
      )}
    </Stack.Navigator>
  );
}
```

